// Vertrag Modul 01 → Cockpit (siehe README „Anbindung Modul 01“). Verarbeitet alle Items.
// Erwartet: { objektId | objektName, quelle: 'modul01', stand?, dokumente: [{ name, status }],
//             kennwerte?: [{ feld, wert, quelle, pruefstatus }], freigaben?: [{ investorEmail, freigegebenAm }],
//             objekt?: { name, adresse, stadt, assetklasse, flaeche, kaufpreisMio } }   ← Create deal (Nino, 28.08.)
const MAP = { ok: 'vorhanden', done: 'vorhanden', available: 'vorhanden', vorhanden: 'vorhanden',
              pruefung: 'in_pruefung', in_pruefung: 'in_pruefung', review: 'in_pruefung', 'in prüfung': 'in_pruefung',
              fehlt: 'ausstehend', offen: 'ausstehend', missing: 'ausstehend', ausstehend: 'ausstehend' };
return $input.all().map(({ json }) => {
  const d = json.body ?? json;
  const dokumente = (d.dokumente ?? []).map((x) => ({
    name: String(x.name ?? '').trim(),
    status: MAP[String(x.status ?? '').toLowerCase()] ?? 'ausstehend',
  })).filter((x) => x.name);
  const kennwerte = (d.kennwerte ?? []).map((k) => ({
    feld: String(k.feld ?? ''), wert: String(k.wert ?? ''), quelle: String(k.quelle ?? ''),
    pruefstatus: k.pruefstatus === 'uebernommen' ? 'uebernommen' : 'pruefen',
  }));
  const vorhanden = dokumente.filter((x) => x.status === 'vorhanden').length;
  return { json: {
    objektId: d.objektId ?? null, objektName: d.objektName ?? d.objekt?.name ?? null,
    objekt: d.objekt ?? null, // gefüllt = Modul 01 hat einen neuen Datenraum angelegt → Deal im Cockpit anlegen
    quelle: 'modul01', stand: d.stand ?? new Date().toISOString(),
    dokumente, kennwerte, freigaben: d.freigaben ?? [], vorhanden, gesamt: dokumente.length,
    // Platzhalter: Lookup gegen die Cockpit-Ablage – bis dahin gilt: bekannt, wenn eine objektId mitkommt
    imCockpitBekannt: Boolean(d.objektId),
  } };
});
